mapper.update:
UPDATE gw_approval_doc
   SET status_cd = 'IN_PROGRESS', submitted_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
 WHERE doc_id = #{docId}

UPDATE gw_approval_doc
   SET status_cd = #{statusCd}, completed_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
 WHERE doc_id = #{docId}

UPDATE gw_approval_line
   SET status_cd = #{statusCd}, comment = #{comment}, acted_at = CURRENT_TIMESTAMP
 WHERE line_id = #{lineId}

mapper.select:
SELECT d.*, f.form_cd, f.form_nm, u.name AS drafter_name, dept.dept_nm AS drafter_dept FROM gw_approval_doc d JOIN gw_approval_form f ON f.form_id = d.form_id JOIN gw_user u ON u.user_id = d.drafter_id LEFT JOIN gw_dept dept ON dept.dept_id = u.dept_id WHERE d.drafter_id = #{drafterId}
AND d.status_cd = #{status}
ORDER BY d.created_at DESC LIMIT 200

SELECT DISTINCT d.*, f.form_cd, f.form_nm, u.name AS drafter_name, dept.dept_nm AS drafter_dept FROM gw_approval_doc d JOIN gw_approval_form f ON f.form_id = d.form_id JOIN gw_user u ON u.user_id = d.drafter_id LEFT JOIN gw_dept dept ON dept.dept_id = u.dept_id JOIN gw_approval_line l ON l.doc_id = d.doc_id WHERE l.approver_id = #{approverId} AND l.status_cd IN ('APPROVED','REJECTED')
AND d.status_cd = #{status}
ORDER BY d.completed_at DESC NULLS LAST, d.updated_at DESC LIMIT 200
